<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import ErpLayout from '@/Layouts/ErpLayout.vue';defineOptions({layout:ErpLayout});const props=defineProps<{statements:Array<{id:number;label:string}>;selectedStatementId:number|null}>();const form=useForm({bank_statement_import_id:props.selectedStatementId,notes:''});const submit=():void=>form.post(route('bank-reconciliations.store'));</script>
<template><Head title="Start Bank Reconciliation"/><form class="space-y-6" @submit.prevent="submit"><div><Link :href="route('bank-reconciliations.index')" class="text-sm text-brand-600">Bank Reconciliations</Link><h1 class="mt-2 text-2xl font-semibold">Start Bank Reconciliation</h1><p class="mt-1 text-sm text-gray-500">Select one imported statement that is not already being reconciled.</p></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><label class="space-y-1 text-sm">Bank Statement<select v-model="form.bank_statement_import_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select a statement</option><option v-for="s in statements" :key="s.id" :value="s.id">{{s.label}}</option></select><span class="text-xs text-error-500">{{form.errors.bank_statement_import_id}}</span></label><label class="mt-5 block space-y-1 text-sm">Notes<textarea v-model="form.notes" rows="5" maxlength="4000" class="w-full rounded-lg border p-3 dark:border-gray-700"/></label></div><p v-if="statements.length===0" class="rounded-xl border border-warning-200 bg-warning-50 p-4 text-sm text-warning-700">No imported statement is currently available.</p><div class="flex justify-end gap-3"><Link :href="route('bank-reconciliations.index')" class="rounded-lg border px-5 py-2.5 text-sm dark:border-gray-700">Cancel</Link><button :disabled="form.processing||form.bank_statement_import_id===null" class="rounded-lg bg-brand-500 px-5 py-2.5 text-sm text-white disabled:opacity-50">Create Session</button></div></form></template>
